class Program
{
    static void Main(string[] args) { }
    void M1(string x)
    {
        switch (x)
        {
            case "a":
            case "b" when Mutate(ref x): // prevents sharing temps
            case "c":
                break;
        }
    }
    void M2(string x)
    {
        switch (x)
        {
            case "a":
            case "b" when Pure(x):
            case "c":
                break;
        }
    }
    static bool Mutate(ref string x) { x = null; return false; }
    static bool Pure(string x) { return false; }
}
